use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let obj = input.as_object().unwrap();
    let shift = obj["shift"].as_i64().unwrap();
    let text = obj["text"].as_str().unwrap();

    let mut result = String::new();
    for c in text.chars() {
        if c.is_ascii_lowercase() {
            let shifted = ((c as u8 - b'a' + shift as u8) % 26) + b'a';
            result.push(shifted as char);
        } else {
            result.push(c);
        }
    }

    json!({ "result": result })
}
